mapper.select:
SELECT S.*, SC.SupplyName AS SupplyName
FROM shopwizard.tCmpShop S
INNER JOIN shopwizard.tCmpSupplyComp SC ON S.SupplyCode = SC.SupplyCode

INNER JOIN shopwizard.tCmpShopWarehs SW ON S.ShopCode = SW.ShopCode


    AND S.SvcCode = #{pSvcCode}
    AND S.ShopCode = #{pShopCode}
    AND S.SupplyCode = #{pSupplyCode}
    AND S.ShopName LIKE CONCAT('%',#{pShopName},'%')
    AND S.State = #{pState}
    AND S.AdjustPeriodCode = #{pAdjustPeriodCode}
    AND S.MngrMd = #{pMngrMd}
    AND S.AutoOrderYn = #{pAutoOrderYn}
    AND SW.WarehsCode = #{pWarehsCode}


    ORDER BY ${sidx} ${sord}
    ORDER BY ShopName

LIMIT ${pPageOffset}, ${pPageSize}

SELECT COUNT(*)
FROM shopwizard.tCmpShop S
INNER JOIN shopwizard.tCmpSupplyComp SC ON S.SupplyCode = SC.SupplyCode

    AND S.SvcCode = #{pSvcCode}
    AND S.ShopCode = #{pShopCode}
    AND S.SupplyCode = #{pSupplyCode}
    AND S.ShopName LIKE CONCAT('%',#{pShopName},'%')
    AND S.State = #{pState}
    AND S.AdjustPeriodCode = #{pAdjustPeriodCode}
    AND S.MngrMd = #{pMngrMd}
    AND S.AutoOrderYn = #{pAutoOrderYn}

SELECT MAX(ShopCode)
FROM shopwizard.tCmpShop
WHERE SupplyCode = #{value}

SELECT COUNT(*)
FROM shopwizard.tCmpShop

    AND LoginId = #{pLoginId}
